import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Keynote- Open Source Community Engagement- We’re in. Are you? - Matthew Leonard, Bloomberg","description":"","frontmatter":{"title":"Keynote- Open Source Community Engagement- We’re in. Are you? - Matthew Leonard, Bloomberg","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph社区","开源存储","分布式存储","开源参与","Ceph生态系统"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Open_Source_Community_Engagement_-_We_re_in._Are_you_-_Matthew_Leonard_Bloomberg.md","filePath":"posts/2025/Keynote_-_Open_Source_Community_Engagement_-_We_re_in._Are_you_-_Matthew_Leonard_Bloomberg.md","lastUpdated":1780459816000}'),n={name:"posts/2025/Keynote_-_Open_Source_Community_Engagement_-_We_re_in._Are_you_-_Matthew_Leonard_Bloomberg.md"};function a(i,o,s,g,_,h){return r(),t("div",null,[...o[0]||(o[0]=[l('<h3 id="会议纪要-ceph开源社区的参与与合作" tabindex="-1">会议纪要：Ceph开源社区的参与与合作 <a class="header-anchor" href="#会议纪要-ceph开源社区的参与与合作" aria-label="Permalink to &quot;会议纪要：Ceph开源社区的参与与合作&quot;">​</a></h3><p><strong>会议主题</strong>: Ceph开源社区的参与与合作<br><strong>主讲人</strong>: Bloomberg代表 Matthew Leonard<br><strong>会议内容概述</strong>:<br> Bloomberg代表分享了Bloomberg在Ceph开源社区的参与历程，强调了社区合作的重要性，并提出了如何通过多层次的参与来推动Ceph项目的发展。</p><h4 id="_1-开源社区的定义与重要性" tabindex="-1">1. <strong>开源社区的定义与重要性</strong> <a class="header-anchor" href="#_1-开源社区的定义与重要性" aria-label="Permalink to &quot;1. **开源社区的定义与重要性**&quot;">​</a></h4><ul><li><strong>讨论</strong>: 开源不仅仅是个人行为，而是社区行动。Bloomberg认为，开源项目的成功依赖于一个协调的社区，社区的愿景和目标是项目成功的关键。</li><li><strong>关键点</strong>: <ul><li>开源项目需要社区的多样性和强有力的支持。</li><li>Bloomberg作为一家金融公司，采用“开源优先”的策略，积极参与开源项目。</li></ul></li></ul><h4 id="_2-bloomberg在ceph社区的参与历程" tabindex="-1">2. <strong>Bloomberg在Ceph社区的参与历程</strong> <a class="header-anchor" href="#_2-bloomberg在ceph社区的参与历程" aria-label="Permalink to &quot;2. **Bloomberg在Ceph社区的参与历程**&quot;">​</a></h4><ul><li><strong>四个阶段</strong>: <ol><li><strong>消费</strong>: 2013年，Bloomberg开始使用Ceph作为OpenStack的RBD后端，支持虚拟化平台。</li><li><strong>参与</strong>: 2014年，Bloomberg开始向社区反馈问题，参与社区讨论。</li><li><strong>贡献</strong>: 近年来，Bloomberg不仅贡献代码，还通过基金会成员身份提供资金和时间支持。</li><li><strong>领导</strong>: Bloomberg员工已进入Ceph指导委员会，并在基金会中担任代表角色。</li></ol></li></ul><h4 id="_3-社区合作的核心理念" tabindex="-1">3. <strong>社区合作的核心理念</strong> <a class="header-anchor" href="#_3-社区合作的核心理念" aria-label="Permalink to &quot;3. **社区合作的核心理念**&quot;">​</a></h4><ul><li><strong>从“我”到“我们”</strong>: Bloomberg强调，社区的成功不是单个公司的成功，而是整个社区的共同成功。项目的强弱取决于其最薄弱的环节，只有共同努力才能推动项目前进。</li><li><strong>行动计划</strong>: <ul><li>打破用户与开发者之间的壁垒，促进用户与开发者的互动。</li><li>推动用户开发者峰会的持续发展，确保用户反馈得到有效响应。</li></ul></li></ul><h4 id="_4-ceph项目的自我反思与改进" tabindex="-1">4. <strong>Ceph项目的自我反思与改进</strong> <a class="header-anchor" href="#_4-ceph项目的自我反思与改进" aria-label="Permalink to &quot;4. **Ceph项目的自我反思与改进**&quot;">​</a></h4><ul><li><strong>项目优势与劣势</strong>: Bloomberg认为，Ceph需要明确自身的优势和劣势，并持续优化。项目不应试图满足所有需求，而应专注于核心竞争力。</li><li><strong>缩短反馈循环</strong>: 通过加强用户与开发者之间的沟通，缩短反馈路径，确保项目的改进能够及时响应用户需求。</li></ul><h4 id="_5-推动社区的统一与参与" tabindex="-1">5. <strong>推动社区的统一与参与</strong> <a class="header-anchor" href="#_5-推动社区的统一与参与" aria-label="Permalink to &quot;5. **推动社区的统一与参与**&quot;">​</a></h4><ul><li><strong>用户与开发者的统一</strong>: Bloomberg认为，用户和开发者应该形成一个统一的社区，而不是两个独立的群体。只有通过共同努力，才能推动项目的发展。</li><li><strong>扩大参与</strong>: Bloomberg希望通过更多的用户和开发者参与，推动Ceph项目的广泛应用，并吸引更多贡献者和领导者。</li></ul><h4 id="_6-未来挑战与机会" tabindex="-1">6. <strong>未来挑战与机会</strong> <a class="header-anchor" href="#_6-未来挑战与机会" aria-label="Permalink to &quot;6. **未来挑战与机会**&quot;">​</a></h4><ul><li><strong>Ceph的未来</strong>: Ceph作为分布式存储领域的领导者，面临着新的挑战和机遇。Bloomberg认为，Ceph需要通过协调的社区努力，抓住市场机会，确保项目的持续成功。</li><li><strong>行动计划</strong>: <ul><li>明确项目的关键挑战和机会，集中资源应对。</li><li>推动社区的透明化和去中心化，使新成员能够快速融入并贡献。</li></ul></li></ul><h4 id="_7-领导力与战略愿景" tabindex="-1">7. <strong>领导力与战略愿景</strong> <a class="header-anchor" href="#_7-领导力与战略愿景" aria-label="Permalink to &quot;7. **领导力与战略愿景**&quot;">​</a></h4><ul><li><strong>战略与执行的平衡</strong>: 社区需要领导者来平衡日常执行与长期战略愿景。Bloomberg强调，每个贡献都应与项目的长期目标相关联，确保资源的高效利用。</li><li><strong>行动计划</strong>: <ul><li>通过基金会和社区委员会，推动项目的战略规划和执行。</li><li>鼓励更多社区成员参与领导角色，确保项目的持续发展。</li></ul></li></ul><h4 id="_8-总结与呼吁" tabindex="-1">8. <strong>总结与呼吁</strong> <a class="header-anchor" href="#_8-总结与呼吁" aria-label="Permalink to &quot;8. **总结与呼吁**&quot;">​</a></h4><ul><li><strong>社区的健康发展</strong>: Bloomberg认为，一个健康的开源社区需要消费、参与、贡献和领导四个层次的平衡。每个成员都在自己的旅程中，项目的成功依赖于所有成员的共同努力。</li><li><strong>呼吁行动</strong>: 不要问Ceph能为你做什么，而要问你能为Ceph做什么。Bloomberg呼吁社区成员积极参与，共同推动Ceph项目的成功。</li></ul><p><strong>决定事项与后续行动计划</strong>:</p><ol><li><strong>推动用户开发者峰会的持续发展</strong>，确保用户反馈得到有效响应。</li><li><strong>明确Ceph项目的优势与劣势</strong>，制定相应的改进计划。</li><li><strong>缩短用户与开发者之间的反馈循环</strong>，确保项目的改进能够及时响应用户需求。</li><li><strong>推动社区的统一与参与</strong>，吸引更多用户和开发者加入Ceph项目。</li><li><strong>加强社区的透明化和去中心化</strong>，使新成员能够快速融入并贡献。</li></ol>',20)])])}const p=e(n,[["render",a]]);export{m as __pageData,p as default};
